oxy_webhelp_navlinks = {"everpure_flasharray-d39536e52369":{"topics":[{"title":"Everpure FlashArray volume protection architecture and data flow","shortdesc":"<p class=\"shortdesc\">Everpure FlashArray volume protection in <span class=\"ph\">RSC<\/span> uses a two-tier         architecture with FlashArray-native snapshots and incremental changed-block         tracking.<\/p>","href":"saas\/everpure_volume_protection_arch_data_flow.html","attributes":{"data-id":"everpure_volume_protection_arch_data_flow"},"menu":{"hasChildren":false},"tocID":"everpure_volume_protection_arch_data_flow-d39536e52383","topics":[]},{"title":"Set up Everpure FlashArray","shortdesc":"<p class=\"shortdesc\">Add an Everpure FlashArray to <span class=\"ph\">RSC<\/span>, configure the connection, and         assign protection policies to its Protection Groups and volumes.<\/p>","href":"saas\/everpure_flasharray_setup.html","attributes":{"data-id":"everpure_flasharray_setup"},"menu":{"hasChildren":false},"tocID":"everpure_flasharray_setup-d39536e52397","next":"everpure_flasharray_setup-d39536e52397"},{"title":"Manage Everpure FlashArray","shortdesc":"<p class=\"shortdesc\">Configure application-consistent backups and monitor protection activity for         Everpure FlashArray Protection Groups.<\/p>","href":"saas\/everpure_flasharray_management.html","attributes":{"data-id":"everpure_flasharray_management"},"menu":{"hasChildren":false},"tocID":"everpure_flasharray_management-d39536e52472","next":"everpure_flasharray_management-d39536e52472"},{"title":"Recover Everpure FlashArray volumes","shortdesc":"<p class=\"shortdesc\">You can recover an Everpure FlashArray volume by exporting a snapshot to a target         FlashArray. Every recovery creates a new volume on the target FlashArray.<\/p>","href":"saas\/everpure_volume_recovery.html","attributes":{"data-id":"everpure_volume_recovery"},"menu":{"hasChildren":false},"tocID":"everpure_volume_recovery-d39536e52505","topics":[]}]}};